solution.Time.java:
public final class Time {
    static final Time MIDNIGHT = new Time(0, 0);
    static final Time NOON = new Time(12, 0);

    private final int hour, minute;

    private Time(int hour, int minute) {
        this.hour = hour;
        this.minute = minute;
    }

    static Time of(int hour, int minute) {
        if (hour < 0 || hour > 23) throw new IllegalArgumentException("bad hour " + hour);
        if (minute < 0 || minute > 59) throw new IllegalArgumentException("bad minute " + minute);
        return new Time(hour, minute);
    }

    static Time parse(String text) {
        String t = text.trim();
        if (!t.matches("\\d{1,2}:\\d{2}")) throw new IllegalArgumentException("not a time: " + text);
        String[] parts = t.split(":");
        return of(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
    }

    private int total() { return hour * 60 + minute; }

    Time plusMinutes(int minutes) {
        int m = Math.floorMod(total() + minutes, 24 * 60);
        return new Time(m / 60, m % 60);
    }

    int minutesUntil(Time later) {
        return Math.floorMod(later.total() - total(), 24 * 60);
    }

    boolean isBefore(Time other) { return total() < other.total(); }

    @Override
    public String toString() { return String.format("%02d:%02d", hour, minute); }

    @Override
    public boolean equals(Object o) {
        return o instanceof Time t && t.hour == hour && t.minute == minute;
    }

    @Override
    public int hashCode() { return total(); }
}

hints:
`equals` takes an `Object`: check the type with `o instanceof Time t`, which also gives you `t` as a `Time`, then compare fields. Equal objects must have equal hash codes. For a class with two `int` fields it looks like this (lesson 3.03 covers `equals` and `hashCode` fully):

```java-norun
@Override
public boolean equals(Object o) {
    return o instanceof Point p && p.x == x && p.y == y;   // false for null or another type
}

@Override
public int hashCode() { return 31 * x + y; }               // equal points give equal numbers
```

unitTests:
test("creating and printing", () -> {
    checkEq(Time.of(9, 5).toString(), "09:05");
    checkEq(Time.MIDNIGHT.toString(), "00:00");
    checkEq(Time.NOON.toString(), "12:00");
    checkThrows(IllegalArgumentException.class, () -> Time.of(24, 0));
    checkThrows(IllegalArgumentException.class, () -> Time.of(10, 60));
    checkThrows(IllegalArgumentException.class, () -> Time.of(-1, 0));
});

test("parsing", () -> {
    checkEq(Time.parse("9:05"), Time.of(9, 5));
    checkEq(Time.parse(" 23:59 "), Time.of(23, 59));
    for (String bad : new String[] {"9:5", "925", "24:00", "ab:cd", "", "9:005"}) {
        checkThrows(IllegalArgumentException.class, () -> Time.parse(bad));
    }
});

test("arithmetic without changing", () -> {
    Time t = Time.of(23, 30);
    checkEq(t.plusMinutes(45).toString(), "00:15");
    checkEq(t.plusMinutes(-24 * 60 - 30).toString(), "23:00");
    checkEq(t.toString(), "23:30");
    checkEq(Time.of(23, 0).minutesUntil(Time.of(1, 0)), 120);
    checkEq(Time.of(8, 0).minutesUntil(Time.of(8, 0)), 0);
    checkEq(Time.of(8, 0).isBefore(Time.NOON), true);
    checkEq(Time.NOON.isBefore(Time.NOON), false);
});

test("equality", () -> {
    checkEq(Time.of(7, 45).equals(Time.parse("07:45")), true);
    checkEq(Time.of(7, 45).equals("07:45"), false);
    checkEq(new java.util.HashSet<>(java.util.List.of(Time.of(1, 1), Time.of(1, 1), Time.of(2, 2))).size(), 2);
});

